// Kelas generic
class Kotak<T> {
  private isi: T[] = [];

  constructor(private muat: number) {}

  get jumlah(): number {
    return this.isi.length;
  }

  masuk(x: T): boolean {
    if (this.isi.length >= this.muat) return false;
    this.isi.push(x);
    return true;
  }

  keluar(): T | undefined {
    return this.isi.shift();
  }

  toString(): string {
    return `[${this.isi.join(", ")}] ${this.jumlah}/${this.muat}`;
  }
}

